struct TempFile {
    path: Str,
}

@before_each
fn create_temp_file() -> TempFile {
    let path = "/tmp/test_{random}.txt"
    io.println("Creating temp file: {path}")
    return TempFile { path }
}

@after_each
fn remove_temp_file(f: TempFile) {
    io.println("Removing temp file: {f.path}")
}

@test
fn test_write_to_temp(f: TempFile) {
    io.println("Writing to {f.path}")
    assert(f.path.starts_with("/tmp/"))
}

@test
fn test_read_from_temp(f: TempFile) {
    io.println("Reading from {f.path}")
    assert(f.path.len() > 5)
}
